/**
 * @summary Delete at Meta. Approved names cannot be reused for 30 days.
 */
export const getDeleteTemplateUrl = (organizationId: string,
    templateId: string,
    params?: DeleteTemplateParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/organizations/${organizationId}/templates/${templateId}?${stringifiedParams}` : `/organizations/${organizationId}/templates/${templateId}`
}

